INSERT INTO public.form_field (id, form_id, section_id, label, name, description, type, placeholder, required, disabled, validation, error_message, prefix, "position", is_active, version) VALUES (24, 1, 3, '{"en": "Country of Undergraduate Degree", "pt": "País da instituição de ensino da graduação"}', 'country-undergraduate', '{"en": "Country where you acquired your undergraduate degree.", "pt": "País no qual sua graduação foi obtida."}', 'Text', 'Brasil', true, false, NULL, '{}', NULL, 5, true, 1);
INSERT INTO public.form_field (id, form_id, section_id, label, name, description, type, placeholder, required, disabled, validation, error_message, prefix, "position", is_active, version) VALUES (25, 1, 3, '{"en": "Undergraduate Studies Transcripts", "pt": "Histórico escolar de graduação"}', 'studies-transcripts', '{"en": "Digital copy of you academic transcripts.", "pt": "Cópia digitalizada do seu histórico oficial de graduação, com as disciplinas cursadas e as respectivas avaliações."}', 'File', NULL, true, false, NULL, '{}', NULL, 6, true, 1);
INSERT INTO public.form_field (id, form_id, section_id, label, name, description, type, placeholder, required, disabled, validation, error_message, prefix, "position", is_active, version) VALUES (26, 1, 3, '{"en": "Year of POSCOMP Exam (if taken)", "pt": "Ano de realização do POSCOMP (se realizado)"}', 'year-poscomp', '{"en": "
If you have taken the [POSCOMP](https://www.sbc.org.br/poscomp/) exam, inform the year. If you have taken the exame more than once, inform the year whose grades you wish to use. Skip this question if you have not taken the exam.
", "pt": "
Informe o ano em que você realizou o exame do [POSCOMP](https://www.sbc.org.br/poscomp/). Se você fez mais de uma vez, escolha o ano do exame que deseja utilizar. Se não fez o exame, pule a questão 
