INSERT INTO public.form_field (id, form_id, section_id, label, name, description, type, placeholder, required, disabled, validation, error_message, prefix, "position", is_active, version) VALUES (27, 1, 3, '{"en": "Grades in the POSCOMP Exam (if available)", "pt": "Nota no POSCOMP (se realizado)"}', 'grades-poscomp', '{"en": "
Total score in the [POSCOMP](https://www.sbc.org.br/poscomp/) exam, as informed in the previous item. If you have taken the exame but do not know your score, leave it blank. Skip this question if you have not taken the exam.
